<?php require_once __DIR__ . '/_logistics_common.php';
$q = logi_query_value();
$allRows=$pdo->query('SELECT doc.*, a.designation asset_name, d.full_name driver_name FROM logistics_documents doc LEFT JOIN logistics_assets a ON a.id=doc.asset_id LEFT JOIN logistics_drivers d ON d.id=doc.driver_id ORDER BY doc.id DESC LIMIT 500')->fetchAll(PDO::FETCH_ASSOC);
$rows = logi_filter_rows($allRows, ['document_type','reference_number','asset_name','driver_name','expires_at','file_path','status'], $q);
logi_page_start('Documents administratifs','Assurances, cartes grises, visites techniques, licences et permis.');
logi_listing_toolbar('documents_form.php', 'documents', $q, 'Rechercher document, reference, ressource, chauffeur...');
logi_card_open('Documents suivis', ($q !== '' ? count($rows) . ' resultat(s)' : 'Controle administratif et alertes d expiration')); ?>
<div class="overflow-x-auto"><table class="w-full border-separate border-spacing-y-3"><thead><tr class="text-left text-xs uppercase tracking-[0.18em] text-slate-500"><th class="px-4">Document</th><th>Ressource</th><th>Chauffeur</th><th>Expiration</th><th>Fichier</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): $expired=$r['expires_at'] && strtotime($r['expires_at'])<time(); ?><tr class="bg-white shadow-sm"><td class="px-4 py-4 rounded-l-2xl"><div class="font-semibold"><?= logi_h($r['document_type']) ?></div><div class="text-sm text-slate-500"><?= logi_h($r['reference_number']) ?></div></td><td><?= logi_h($r['asset_name']) ?></td><td><?= logi_h($r['driver_name']) ?></td><td><?= logi_h($r['expires_at']) ?></td><td><?= $r['file_path']?'<a class="text-orange-600 font-semibold" href="'.logi_h($r['file_path']).'" target="_blank">Ouvrir</a>':'-' ?></td><td class="rounded-r-2xl"><?= logi_badge($expired?'expired':$r['status']) ?></td></tr><?php endforeach; ?><?php if(empty($rows)): ?><tr><td colspan="6" class="py-8 text-center text-slate-400">Aucun document trouve.</td></tr><?php endif; ?></tbody></table></div>
<?php logi_card_close(); logi_page_end();
